#include <stdlib.h>
#include <string.h>
#include <event2/buffer.h>
#include <event2/bufferevent.h>
#include <event2/listener.h>

void handle_line(const char *line, size_t len);

static void on_read(struct bufferevent *bev, void *ctx) {
  char buf[512];
  size_t n;
  while ((n = bufferevent_read(bev, buf, sizeof(buf) - 1)) > 0) {
    buf[n] = '\0';
    char *save = NULL;
    for (char *line = strtok_r(buf, "\r\n", &save); line != NULL; line = strtok_r(NULL, "\r\n", &save)) {
      handle_line(line, strlen(line));
    }
  }
}

static void on_event(struct bufferevent *bev, short events, void *ctx) {
  if (events & (BEV_EVENT_EOF | BEV_EVENT_ERROR)) {
    bufferevent_free(bev);
  }
}

void on_accept(struct evconnlistener *listener, evutil_socket_t fd, struct sockaddr *addr, int socklen, void *ctx) {
  struct event_base *base = evconnlistener_get_base(listener);
  struct bufferevent *bev = bufferevent_socket_new(base, fd, 0);
  bufferevent_setcb(bev, on_read, NULL, on_event, NULL);
  bufferevent_enable(bev, EV_READ);
}

